/**
 * ORANGE SHIELD - ENGINE 04 · SPOOF DETECTOR
 *
 * Anti-spoofing identification in FOUR steps (the requested pipeline):
 *
 *   PASSO 1 · FORMATO — validates the number itself: country code,
 *     ANATEL DDD, 9th-digit length rule and synthetic digit patterns
 *     (mass repetition / long sequences) generated by spoofing software.
 *   PASSO 2 · APRESENTAÇÃO — how the caller ID presents itself:
 *     local numbers displayed in invalid international formats (e.g. DDD 00
 *     after +55), excess digits beyond the national plan, Brazilian numbers
 *     masked behind foreign country codes and NEIGHBOR SPOOFING (calls that
 *     mimic the user's own number).
 *   PASSO 3 · FREQUÊNCIA — call-rate heuristics over the screening history:
 *     Wangiri rapid redial ("one ring and hang up") and same-DDD calling
 *     waves (mass-burst spoofing).
 *   PASSO 4 · REPUTAÇÃO — local reputation base: confirmed fraud,
 *     collective reports (denúncias) and robocall/telemarketing
 *     classification learned from the community.
 *
 * Output: per-step status + flat check list + spoof score 0-100, consumed by
 * the Call Guard (as evidences), the WhatsApp Guard, the Lookup API and the
 * dedicated Anti-Spoofing panel.
 */

import { db } from "@/lib/db";
import { clampScore } from "./types";

export const SPOOF_WEIGHTS = {
  // Passo 1 · Formato
  INVALID_DDD: 30,
  BAD_LENGTH: 25,
  BAD_INTL_LENGTH: 25,
  REPEATED_DIGITS: 25,
  SEQUENTIAL_DIGITS: 20,
  // Passo 2 · Apresentação
  INTERNATIONAL_ANOMALY: 35,
  EXCESS_LENGTH: 30,
  INTL_MASKED_BR: 25,
  NEIGHBOR_SPOOF: 35,
  // Passo 3 · Frequência
  RAPID_REDIAL: 40,
  PREFIX_BURST: 30,
  // Passo 4 · Reputação
  REPUTATION_FRAUD: 100,
  REPUTATION_REPORTS: 40,
  REPUTATION_CLASS: 30,
} as const;

/** DDDs assigned by ANATEL (Brazilian numbering plan). */
export const VALID_DDDS = new Set([
  11, 12, 13, 14, 15, 16, 17, 19, 21, 22, 24, 27, 28, 31, 32, 33, 34, 35, 37,
  38, 41, 42, 43, 44, 45, 46, 47, 48, 49, 51, 53, 54, 55, 61, 62, 63, 64, 65,
  66, 67, 68, 69, 71, 73, 74, 75, 77, 79, 81, 82, 83, 84, 85, 86, 87, 88, 89,
  91, 92, 93, 94, 95, 96, 97, 98, 99,
]);

/** Metadata of the four-step spoofing pipeline. */
export const SPOOF_STEPS = [
  {
    id: 1,
    code: "FORMAT",
    title: "Passo 1 · Formato do número",
    description:
      "Valida a estrutura do caller ID: código de país, DDD da ANATEL, regra do nono dígito e padrões sintéticos de dígitos.",
  },
  {
    id: 2,
    code: "PRESENTATION",
    title: "Passo 2 · Apresentação internacional",
    description:
      "Detecta número local exibido em formato internacional inválido, excesso de dígitos, BR mascarado atrás de código estrangeiro e neighbor spoofing.",
  },
  {
    id: 3,
    code: "FREQUENCY",
    title: "Passo 3 · Frequência de chamadas",
    description:
      "Analisa o ritmo de chamadas no histórico: rediscagem rápida (Wangiri) e ondas de disparo no mesmo DDD.",
  },
  {
    id: 4,
    code: "REPUTATION",
    title: "Passo 4 · Reputação do número",
    description:
      "Consulta a base local de reputação: golpe confirmado, denúncias coletivas e classificação (robocall/telemarketing).",
  },
] as const;

export type SpoofStepCode = (typeof SPOOF_STEPS)[number]["code"];

export interface SpoofCheck {
  code: string;
  label: string;
  detail: string;
  points: number;
  status: "pass" | "flagged" | "info";
}

export interface SpoofStepResult {
  id: number;
  code: SpoofStepCode;
  title: string;
  description: string;
  status: "pass" | "flagged" | "info";
  points: number;
  checks: SpoofCheck[];
}

export interface SpoofAnalysis {
  checks: SpoofCheck[];
  steps: SpoofStepResult[];
  spoofScore: number;
  verdict: "clean" | "suspicious" | "spoof_likely";
  verdictLabel: string;
}

export function spoofVerdict(score: number): {
  verdict: SpoofAnalysis["verdict"];
  verdictLabel: string;
} {
  if (score >= 55) {
    return { verdict: "spoof_likely", verdictLabel: "Spoofing provável" };
  }
  if (score >= 25) {
    return { verdict: "suspicious", verdictLabel: "Indícios de spoofing" };
  }
  return { verdict: "clean", verdictLabel: "Nenhum indício de spoofing" };
}

/**
 * Parses a +55 number into { ddd, local }.
 * Returns null for shortcodes/international/alphanumeric senders.
 */
export function parseBrazilNumber(e164: string): { ddd: string; local: string } | null {
  const m = e164.match(/^\+55(\d{2})(\d{8,9})$/);
  if (!m) return null;
  return { ddd: m[1], local: m[2] };
}

/** 0303/0800/0300 service numbers use a dedicated numbering plan. */
export function isServiceNumber(e164: string): boolean {
  return /^\+55(0303|0800|0300)/.test(e164);
}

/** True when the caller ID carries no digits at all (SMS alphanumeric sender). */
function isAlphanumeric(e164: string): boolean {
  return /\D/.test(e164.slice(1)) || e164.replace(/\D/g, "").length === 0;
}

/** Longest run of the same digit (e.g. "97777777" -> 7). */
function maxRepeatedRun(local: string): number {
  let best = 1;
  let cur = 1;
  for (let i = 1; i < local.length; i++) {
    cur = local[i] === local[i - 1] ? cur + 1 : 1;
    if (cur > best) best = cur;
  }
  return best;
}

/** Longest ascending or descending sequential digit run (e.g. "1234567" -> 7). */
function maxSequentialRun(local: string): number {
  let best = 1;
  let up = 1;
  let down = 1;
  for (let i = 1; i < local.length; i++) {
    const diff = local.charCodeAt(i) - local.charCodeAt(i - 1);
    up = diff === 1 ? up + 1 : 1;
    down = diff === -1 ? down + 1 : 1;
    best = Math.max(best, up, down);
  }
  return best;
}

/** Longest common suffix length between two digit strings. */
function commonSuffixLength(a: string, b: string): number {
  let i = 0;
  while (i < a.length && i < b.length && a[a.length - 1 - i] === b[b.length - 1 - i]) i++;
  return i;
}

/** Longest common prefix length between two digit strings. */
function commonPrefixLength(a: string, b: string): number {
  let i = 0;
  while (i < a.length && i < b.length && a[i] === b[i]) i++;
  return i;
}

// ============================================================================
// PASSO 1 · FORMATO — structural validation of the caller ID
// ============================================================================

export function formatStepChecks(e164: string): SpoofCheck[] {
  // Service numbers (0303/0800/0300) use a dedicated numbering plan:
  // their prefix IS the official ANATEL identification, so DDD/local
  // checks would produce false positives.
  if (isServiceNumber(e164)) {
    return [
      {
        code: "NOT_BRL",
        label: "Formato não-local",
        detail: "Número de serviço (0303/0800/0300) — numeração dedicada",
        points: 0,
        status: "info",
      },
      {
        code: "SERVICE_FORMAT",
        label: "Formato de serviço dedicado",
        detail: "0303/0800/0300 possuem plano próprio — checagem de DDD/local não aplicável",
        points: 0,
        status: "info",
      },
    ];
  }

  const checks: SpoofCheck[] = [];
  const br = parseBrazilNumber(e164);

  if (br) {
    const { ddd, local } = br;
    const dddNum = Number(ddd);
    const isMobileFormat = local.startsWith("9");
    const expectedLen = isMobileFormat ? 9 : 8;

    // 1a. Country code +55 assumed by normalization; DDD validity
    if (!VALID_DDDS.has(dddNum)) {
      checks.push({
        code: "INVALID_DDD",
        label: "DDD inexistente no Brasil",
        detail: `O DDD ${ddd} não existe no plano de numeração da ANATEL — caller ID sintético`,
        points: SPOOF_WEIGHTS.INVALID_DDD,
        status: "flagged",
      });
    } else {
      checks.push({
        code: "VALID_DDD",
        label: `DDD ${ddd} válido`,
        detail: "Área de registro existente no plano da ANATEL",
        points: 0,
        status: "pass",
      });
    }

    // 1b. Length consistency (9th digit rule)
    if (local.length !== expectedLen) {
      const detail = isMobileFormat
        ? `Celular com ${local.length} dígitos — deveria ter 9 (nono dígito ausente, formato pré-2012)`
        : `Fixo com ${local.length} dígitos — deveria ter 8`;
      checks.push({
        code: "BAD_LENGTH",
        label: "Comprimento inválido",
        detail,
        points: SPOOF_WEIGHTS.BAD_LENGTH,
        status: "flagged",
      });
    } else {
      checks.push({
        code: "OK_LENGTH",
        label: "Comprimento válido",
        detail: `${local.length} dígitos coerentes com ${isMobileFormat ? "celular" : "fixo"}`,
        points: 0,
        status: "pass",
      });
    }

    // 1c. Repeated digits (synthetic patterns)
    const repeated = maxRepeatedRun(local);
    if (repeated >= 6) {
      checks.push({
        code: "REPEATED_DIGITS",
        label: "Dígitos repetidos em massa",
        detail: `Sequência de ${repeated} dígitos idênticos ("...${local.slice(0, repeated)}...") — padrão gerado por software`,
        points: SPOOF_WEIGHTS.REPEATED_DIGITS,
        status: "flagged",
      });
    } else {
      checks.push({
        code: "OK_DIGITS",
        label: "Padrão de dígitos normal",
        detail: "Sem repetições anormais",
        points: 0,
        status: "pass",
      });
    }

    // 1d. Sequential digits (8+ consecutive digits are virtually impossible in real numbers)
    const sequential = maxSequentialRun(local);
    if (sequential >= 8) {
      checks.push({
        code: "SEQUENTIAL_DIGITS",
        label: "Sequência numérica artificial",
        detail: `Sequência de ${sequential} dígitos consecutivos — caller ID sintético`,
        points: SPOOF_WEIGHTS.SEQUENTIAL_DIGITS,
        status: "flagged",
      });
    } else {
      checks.push({
        code: "OK_SEQ",
        label: "Sem sequências artificiais",
        detail: "Distribuição de dígitos natural",
        points: 0,
        status: "pass",
      });
    }

    return checks;
  }

  // Not a standard Brazilian number
  checks.push({
    code: "NOT_BRL",
    label: "Formato não-local",
    detail: isServiceNumber(e164)
      ? "Número de serviço (0303/0800/0300) — numeração dedicada"
      : e164.startsWith("+55")
        ? "Número curto/comercial ou formato atípico — checagens de DDD não aplicáveis"
        : "Número internacional — formatação brasileira não aplicável",
    points: 0,
    status: "info",
  });

  // Alphanumeric senders (SMS) carry no digits to validate
  if (isAlphanumeric(e164)) {
    checks.push({
      code: "ALPHANUMERIC_SENDER",
      label: "Remetente alfanumérico",
      detail: "Sem dígitos para validar (ex.: remetente de operadora)",
      points: 0,
      status: "info",
    });
    return checks;
  }

  // International: basic E.164 length validation (7-15 digits)
  const total = e164.replace(/\D/g, "").length;
  if (total < 8 || total > 15) {
    checks.push({
      code: "BAD_INTL_LENGTH",
      label: "Comprimento internacional inválido",
      detail: `${total} dígitos no total — o padrão E.164 permite entre 8 e 15`,
      points: SPOOF_WEIGHTS.BAD_INTL_LENGTH,
      status: "flagged",
    });
  } else {
    checks.push({
      code: "OK_INTL_FORMAT",
      label: "Formato internacional coerente",
      detail: `${total} dígitos dentro do padrão E.164`,
      points: 0,
      status: "pass",
    });
  }

  return checks;
}

// ============================================================================
// PASSO 2 · APRESENTAÇÃO — how the caller ID presents itself
// ============================================================================

function neighborSpoofCheck(e164: string, ownNumber: string): SpoofCheck {
  const ownDigits = (ownNumber ?? "").replace(/\D/g, "");
  const ownLocal =
    ownDigits.startsWith("55") && ownDigits.length >= 12
      ? ownDigits.slice(4) // 55 + DDD(2) + local
      : ownDigits.length >= 8
        ? ownDigits.slice(-9)
        : "";

  if (!ownLocal) {
    return {
      code: "OWN_UNSET",
      label: "Neighbor spoofing não avaliado",
      detail: "Configure o seu número na aba Anti-Spoofing para ativar esta checagem",
      points: 0,
      status: "info",
    };
  }

  const br = parseBrazilNumber(e164);
  const local = br?.local ?? "";
  const ddd = br?.ddd ?? "";

  if (!local || local === ownLocal) {
    return {
      code: local ? "OK_NEIGHBOR" : "NEIGHBOR_SKIP",
      label: local ? "Não imita seu número" : "Neighbor spoofing não avaliado",
      detail: local
        ? "Sem semelhança relevante com o seu número"
        : "Caller ID sem parte local comparável",
      points: 0,
      status: local ? "pass" : "info",
    };
  }

  const sameDdd = ownDigits.startsWith("55") && ownDigits.slice(2, 4) === ddd;
  const prefix = commonPrefixLength(ownLocal, local);
  const suffix = commonSuffixLength(ownLocal, local);
  const neighbor = (sameDdd && prefix >= 5) || suffix >= 7;

  if (neighbor) {
    const how =
      suffix >= 7
        ? `termina com os mesmos ${suffix} dígitos do seu número`
        : `mesmo DDD + ${prefix} dígitos iniciais do seu número`;
    return {
      code: "NEIGHBOR_SPOOF",
      label: "Neighbor spoofing (imita seu número)",
      detail: `Caller ID ${how} — técnica comum para passar pela desconfiança inicial`,
      points: SPOOF_WEIGHTS.NEIGHBOR_SPOOF,
      status: "flagged",
    };
  }

  return {
    code: "OK_NEIGHBOR",
    label: "Não imita seu número",
    detail: "Sem semelhança relevante com o seu número",
    points: 0,
    status: "pass",
  };
}

export function presentationStepChecks(e164: string, ownNumber: string): SpoofCheck[] {
  // Alphanumeric senders have no caller ID presentation to analyze
  if (isAlphanumeric(e164)) {
    return [
      {
        code: "PRESENTATION_SKIP",
        label: "Apresentação não aplicável",
        detail: "Remetente alfanumérico — sem caller ID numérico para analisar",
        points: 0,
        status: "info",
      },
    ];
  }

  if (isServiceNumber(e164)) {
    return [
      {
        code: "PRESENTATION_SKIP",
        label: "Apresentação não aplicável",
        detail: "Números de serviço (0303/0800/0300) não sofrem a manipulação típica de caller ID",
        points: 0,
        status: "info",
      },
      neighborSpoofCheck(e164, ownNumber),
    ];
  }

  const checks: SpoofCheck[] = [];

  if (e164.startsWith("+55")) {
    const national = e164.replace(/\D/g, "").slice(2); // digits after 55

    if (national.startsWith("00")) {
      // Classic anomaly: a local number displayed in a bogus international format
      checks.push({
        code: "INTERNATIONAL_ANOMALY",
        label: "Anomalia internacional (DDD 00 após +55)",
        detail:
          "Número local apresentado em formato internacional inválido (\"+5500…\") — caller ID forjado por software",
        points: SPOOF_WEIGHTS.INTERNATIONAL_ANOMALY,
        status: "flagged",
      });
    } else if (national.length > 11) {
      // National plan maximum: DDD(2) + mobile(9) = 11 digits
      checks.push({
        code: "EXCESS_LENGTH",
        label: "Dígitos excedentes no plano nacional",
        detail: `${national.length} dígitos após o código de país (máximo 11) — caller ID com dados extras forjados`,
        points: SPOOF_WEIGHTS.EXCESS_LENGTH,
        status: "flagged",
      });
    } else {
      checks.push({
        code: "OK_PRESENTATION",
        label: "Apresentação coerente",
        detail: "Número nacional dentro do plano de numeração da ANATEL",
        points: 0,
        status: "pass",
      });
    }
  } else {
    // Foreign country code — check for a Brazilian number masked behind it
    const digits = e164.replace(/\D/g, "");
    const tail = digits.slice(-11);
    const masked = tail.match(/^(\d{2})(9\d{8})$/);
    if (masked && VALID_DDDS.has(Number(masked[1]))) {
      checks.push({
        code: "INTL_MASKED_BR",
        label: "Número brasileiro mascarado como internacional",
        detail: `Terminação "${masked[1]} ${masked[2]}" segue o padrão BR (DDD + celular) atrás de código de país estrangeiro — típico de caller ID forjado`,
        points: SPOOF_WEIGHTS.INTL_MASKED_BR,
        status: "flagged",
      });
    } else {
      checks.push({
        code: "INTL_LEGIT",
        label: "Apresentação internacional",
        detail: "Código de país estrangeiro sem padrão brasileiro embutido",
        points: 0,
        status: "info",
      });
    }
  }

  // Neighbor spoofing (mimics the user's own number)
  checks.push(neighborSpoofCheck(e164, ownNumber));

  return checks;
}

// ============================================================================
// PASSO 3 · FREQUÊNCIA — call-rate heuristics over screening history
// ============================================================================

/** Wangiri: >= 3 screening events for the same number in the last 15 minutes. */
export async function rapidRedialCheck(e164: string): Promise<SpoofCheck> {
  if (isAlphanumeric(e164) || e164.length <= 9) {
    return {
      code: "REDIAL_SKIP",
      label: "Frequência não aplicável",
      detail: "Remetente curto/alfanumérico — sem histórico de chamadas",
      points: 0,
      status: "info",
    };
  }

  const since = new Date(Date.now() - 15 * 60 * 1000);
  const recent = await db.callEvent.count({
    where: { e164, occurredAt: { gte: since } },
  });

  if (recent >= 3) {
    return {
      code: "RAPID_REDIAL",
      label: "Rediscagem rápida (padrão Wangiri)",
      detail: `${recent} triagens nos últimos 15 minutos — esquema "1 toque e desliga" de tarifa premium`,
      points: SPOOF_WEIGHTS.RAPID_REDIAL,
      status: "flagged",
    };
  }
  return {
    code: "OK_REDIAL",
    label: "Sem rediscagem anormal",
    detail: `${recent} triagem(ns) nos últimos 15 minutos`,
    points: 0,
    status: "pass",
  };
}

/** Same-DDD wave: many distinct numbers of one area code calling within 1 hour. */
export async function prefixBurstCheck(e164: string): Promise<SpoofCheck> {
  const br = parseBrazilNumber(e164);
  if (!br) {
    return {
      code: "BURST_SKIP",
      label: "Onda regional não avaliada",
      detail: "Sem DDD brasileiro identificável neste caller ID",
      points: 0,
      status: "info",
    };
  }

  const since = new Date(Date.now() - 60 * 60 * 1000);
  const prefix = `+55${br.ddd}`;
  const events = await db.callEvent.findMany({
    where: { e164: { startsWith: prefix }, occurredAt: { gte: since } },
    select: { e164: true },
  });
  const distinct = new Set(events.map((e) => e.e164)).size;
  const total = events.length;

  if (distinct >= 6 && total >= 10) {
    return {
      code: "PREFIX_BURST",
      label: "Onda de disparo no mesmo DDD",
      detail: `${distinct} números distintos do DDD ${br.ddd} geraram ${total} triagens na última hora — disparo/spoofing em massa na região`,
      points: SPOOF_WEIGHTS.PREFIX_BURST,
      status: "flagged",
    };
  }

  return {
    code: "OK_BURST",
    label: "Sem onda regional",
    detail: `${total} triagem(ns) no DDD ${br.ddd} na última hora (${distinct} número(s) distinto(s))`,
    points: 0,
    status: "pass",
  };
}

export async function frequencyStepChecks(e164: string): Promise<SpoofCheck[]> {
  const [redial, burst] = await Promise.all([rapidRedialCheck(e164), prefixBurstCheck(e164)]);
  return [redial, burst];
}

// ============================================================================
// PASSO 4 · REPUTAÇÃO — local reputation base
// ============================================================================

export async function reputationStepChecks(e164: string): Promise<SpoofCheck[]> {
  const phone = await db.phoneNumber.findUnique({
    where: { e164 },
    include: { reputation: true },
  });
  const rep = phone?.reputation;

  if (!rep) {
    return [
      {
        code: "REPUTATION_UNKNOWN",
        label: "Sem histórico de reputação",
        detail: "Número ainda não avaliado na base local — os passos 1 a 3 respondem sozinhos",
        points: 0,
        status: "info",
      },
    ];
  }

  const checks: SpoofCheck[] = [];

  if (rep.isConfirmedFraud) {
    checks.push({
      code: "REPUTATION_FRAUD",
      label: "Golpe confirmado na base",
      detail: "Denúncias aprovadas confirmaram fraude deste número — evidência máxima",
      points: SPOOF_WEIGHTS.REPUTATION_FRAUD,
      status: "flagged",
    });
  } else if (rep.reportCount > 0) {
    const raw = Math.min(SPOOF_WEIGHTS.REPUTATION_REPORTS, 10 + rep.reportCount * 10);
    checks.push({
      code: "REPUTATION_REPORTS",
      label: `${rep.reportCount} denúncia(s) coletiva(s)`,
      detail: `Confiança ${Math.round(rep.confidence * 100)}% — relatos da comunidade contam contra o caller ID`,
      points: Math.round(raw * (rep.confidence || 0.5)),
      status: "flagged",
    });
  } else {
    checks.push({
      code: "REPUTATION_NO_REPORTS",
      label: "Nenhuma denúncia registrada",
      detail: "Número sem relatos negativos na base local",
      points: 0,
      status: "pass",
    });
  }

  if (["robocall", "telemarketing", "collector"].includes(rep.classification)) {
    checks.push({
      code: "REPUTATION_CLASS",
      label: `Classificado como ${rep.classification}`,
      detail: "A base de reputação associa este número a disparos automáticos/telemarketing",
      points: SPOOF_WEIGHTS.REPUTATION_CLASS,
      status: "flagged",
    });
  } else if (rep.classification === "verified_business") {
    checks.push({
      code: "REPUTATION_VERIFIED",
      label: "Número comercial verificado",
      detail: "Empresa verificada — reputação positiva reduz a suspeita",
      points: 0,
      status: "pass",
    });
  }

  return checks;
}

// ============================================================================
// PIPELINE — assembles the four steps into the spoofing verdict
// ============================================================================

function buildSpoofSteps(groups: Record<SpoofStepCode, SpoofCheck[]>): SpoofStepResult[] {
  return SPOOF_STEPS.map((meta) => {
    const checks = groups[meta.code] ?? [];
    const points = checks.reduce((sum, c) => sum + (c.status === "flagged" ? c.points : 0), 0);
    const status: SpoofStepResult["status"] = checks.some((c) => c.status === "flagged")
      ? "flagged"
      : checks.some((c) => c.status === "pass")
        ? "pass"
        : "info";
    return { ...meta, checks, points, status };
  });
}

/**
 * Full four-step spoofing analysis (format -> presentation -> frequency ->
 * reputation). Read-only: does not record anything.
 */
export async function analyzeSpoofing(
  e164: string,
  ownNumber: string
): Promise<SpoofAnalysis> {
  const format = formatStepChecks(e164);
  const presentation = presentationStepChecks(e164, ownNumber);
  const [frequency, reputation] = await Promise.all([
    frequencyStepChecks(e164),
    reputationStepChecks(e164),
  ]);

  const steps = buildSpoofSteps({
    FORMAT: format,
    PRESENTATION: presentation,
    FREQUENCY: frequency,
    REPUTATION: reputation,
  });
  const checks = steps.flatMap((s) => s.checks);

  const spoofScore = clampScore(
    checks.reduce((sum, c) => sum + (c.status === "flagged" ? c.points : 0), 0)
  );
  const { verdict, verdictLabel } = spoofVerdict(spoofScore);

  return { checks, steps, spoofScore, verdict, verdictLabel };
}
